// 工程新段纯数值/坏档门；没有World或真实Growth资格时不能称攻城已接通。
#include "resident/domains/military/military_siege_engineering_codec.hpp"
#include "resident/domains/military/military_siege_lifecycle_codec.hpp"
#include "resident/domains/military/military_siege_engineering_profile.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {
int checks=0,failures=0;
void check(bool ok,const char* message){++checks;if(!ok){++failures;std::cerr<<message<<'\n';}}
MilitarySiegeEngineeringState state(){MilitarySiegeEngineeringState s;MilitarySiegeEngineeringPreparation p;p.id="military_siege_engineering:12";p.siege_id="siege:9";p.topology_id="topology";p.from_tick=4;p.to_tick=5;p.round=1;MilitarySiegeEngineeringUnit u;u.unit_id="unit";u.army_id="army:8";u.commander_actor_id="actor";u.authored_actor_id="actor";u.command_source={MilitaryUnitCommandSourceKind::army_formation,"army:8"};u.fit_count=101;u.experience=300;u.level=2;p.units.push_back(u);s.preparations.push_back(p);return s;}
}
int main(){
 MilitarySiegeEngineeringRule rule;for(Integer level=0;level<=4;++level){auto normal=military_siege_engineering_assault_base(rule,101,level,false),engine=military_siege_engineering_assault_base(rule,101,level,true);check(normal.ok&&normal.value==22+5*level,"exact original gate formula");check(engine.ok&&engine.value==42+5*level,"actual engine adds20");}
 check(!military_siege_engineering_assault_base(rule,0,2,false).ok,"empty roster cannot assault");check(!military_siege_engineering_assault_base(rule,501,2,false).ok,"out of bound roster");check(!military_siege_engineering_assault_base(rule,20,5,false).ok,"unknown skill level");rule.profile="future";check(!military_siege_engineering_assault_base(rule,20,1,false).ok,"unknown rule rejected");
 auto s=state();check(validate_military_siege_engineering_preparation_shape(s.preparations[0]).ok,"explicit preparation shape");auto value=military_siege_engineering_codec::encode(s);auto decoded=military_siege_engineering_codec::decode(value);check(decoded.ok&&decoded.value.preparations[0].units[0].experience==300,"JSON source round trip");auto duplicate=value;duplicate.as<BoundaryValue::Dict>()->push_back(duplicate.as<BoundaryValue::Dict>()->front());check(!military_siege_engineering_codec::decode(duplicate).ok,"duplicate root key rejected");
 auto bad=s;bad.preparations[0].units[0].level=3;check(!validate_military_siege_engineering_preparation_shape(bad.preparations[0]).ok,"XP level mismatch");bad=s;bad.preparations[0].to_tick=6;check(!validate_military_siege_engineering_preparation_shape(bad.preparations[0]).ok,"must be actual one half day");bad=s;bad.preparations[0].units.push_back(bad.preparations[0].units[0]);check(!validate_military_siege_engineering_preparation_shape(bad.preparations[0]).ok,"duplicate original unit rejected");
 CodecVisitor::Buffer buffer;CodecVisitor writer(buffer);writer.military_codec_version=17;check(military_siege_engineering_codec::visit(writer,s).ok&&writer.finish().ok,"exact17 encode");MilitarySiegeEngineeringState copy;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(buffer));reader.military_codec_version=17;check(military_siege_engineering_codec::visit(reader,copy).ok&&reader.finish().ok&&copy.preparations.size()==1,"exact17 decode");
 for(Integer version:{Integer(0),Integer(15),Integer(16),Integer(18)}){CodecVisitor::Buffer old;CodecVisitor guard(old);guard.military_codec_version=version;check(!military_siege_engineering_codec::visit(guard,s).ok&&old.empty(),"other versions cannot write new tail");}
 check(!validate_military_siege_engineering_checkpoint_layout(17,{}).ok,"17 cannot infer enabled marker");check(!validate_military_siege_engineering_checkpoint_layout(18,{}).ok,"future version rejected");
 // 只验证真实生命周期产品形状/codec；来源读仍须完整Common/军籍先验。
 SiegeTopology topology;topology.id="topology";topology.nodes={{"gate","gate","Gate","field",100},{"inner","inner","Inner","field",0}};
 MilitarySiegeLifecycleFact created;created.id="military_siege_lifecycle:20";created.siege_id="siege:9";created.topology_id=topology.id;created.actor_id="actor";created.cause_id="military:19";created.tick=4;created.after={"active",4,4,1,{{"army:8",0},{"army:10",1}},{{"unit","gate"},{"defender","inner"}},{},{}};
 check(validate_military_siege_lifecycle_shape(created,topology).ok,"created exact initial participation");
 auto advanced=created;advanced.id="military_siege_lifecycle:22";advanced.kind=MilitarySiegeLifecycleKind::advanced;advanced.cause_id="military_siege_engineering:21";advanced.previous_fact_id=created.id;advanced.before=created.after;advanced.tick=5;advanced.after.last_tick=5;advanced.after.round=2;check(validate_military_siege_lifecycle_shape(advanced,topology).ok,"actual one half day participation shape");
 auto broken=advanced;broken.previous_fact_id.clear();check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"missing predecessor rejected");broken=advanced;broken.cause_id.clear();check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"missing preparation cause rejected");broken=advanced;broken.after.unit_nodes.pop_back();check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"advance cannot silently remove soldiers");broken=advanced;broken.after.unit_nodes.emplace_back("invented","gate");check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"advance cannot add soldiers");broken=advanced;broken.after.last_tick=6;broken.after.round=3;check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"skipped half day rejected");broken=advanced;broken.after.armies.emplace_back("foreign",0);check(!validate_military_siege_lifecycle_shape(broken,topology).ok,"advance cannot add army");
 MilitarySiegeLifecycleState life;life.facts={created,advanced};auto json=military_siege_lifecycle_codec::encode(life);auto read=military_siege_lifecycle_codec::decode(json);check(read.ok&&read.value.facts.size()==2&&read.value.facts[1].previous_fact_id==created.id,"lifecycle JSON round trip");
 auto repeated=json;auto* records=repeated.find("facts")->as<BoundaryValue::Array>();auto* after=(*records)[1].find("after")->as<BoundaryValue::Dict>();after->push_back(after->front());check(!military_siege_lifecycle_codec::decode(repeated).ok,"nested participation duplicate rejected");
 CodecVisitor::Buffer both;CodecVisitor w(both);w.military_codec_version=17;check(military_siege_engineering_codec::visit(w,s).ok&&military_siege_lifecycle_codec::visit(w,life).ok&&w.finish().ok,"17 owns both new segments");MilitarySiegeEngineeringState engineering_copy;MilitarySiegeLifecycleState lifecycle_copy;CodecVisitor r(static_cast<const CodecVisitor::Buffer&>(both));r.military_codec_version=17;check(military_siege_engineering_codec::visit(r,engineering_copy).ok&&military_siege_lifecycle_codec::visit(r,lifecycle_copy).ok&&r.finish().ok&&lifecycle_copy.facts[1].before->unit_nodes==created.after.unit_nodes,"17 round trips participation and engineering");
 for(Integer version:{Integer(15),Integer(16),Integer(18)}){CodecVisitor::Buffer bytes;CodecVisitor old(bytes);old.military_codec_version=version;check(!military_siege_lifecycle_codec::visit(old,life).ok&&bytes.empty(),"other selected versions cannot write lifecycle");}
 std::cout<<"SIEGE_ENGINEERING="<<checks<<" FAILURES="<<failures<<" SCOPE=PURE_SHAPE_CODEC\n";return failures?1:0;
}
